            ['start_time' => 758.58, 'end_time' => 760.58, 'target_text' => 'And they don\'t realize Allah gave you the power.', 'source_text' => 'Mereka tidak menyedari bahawa Allah yang telah mengurniakan kamu daya kudrat.', 'order' => 186],
            ['start_time' => 760.58, 'end_time' => 762.18, 'target_text' => 'He gave you the energy.', 'source_text' => 'Dia yang telah menganugerahkan kamu tenaga dan kesihatan.', 'order' => 187],
