            ['start_time' => 765.94, 'end_time' => 769.22, 'target_text' => 'and you should make an effort with all the energies you can', 'source_text' => 'dan kamu mestilah berusaha dengan segala tenaga yang kamu miliki,', 'order' => 190],
            ['start_time' => 769.22, 'end_time' => 770.42, 'target_text' => 'and the wealth you can.', 'source_text' => 'serta dengan segala harta kemampuan yang ada pada dirimu.', 'order' => 191],
            ['start_time' => 770.42, 'end_time' => 773.22, 'target_text' => 'And then you\'ll notice it being accepted one by one.', 'source_text' => 'Dan kemudian anda akan menyaksikan pintu-pintu kemudahan dibuka satu demi satu.', 'order' => 192],
