            ['start_time' => 796.74, 'end_time' => 801.14, 'target_text' => 'But you don\'t look at what negativity might occur.', 'source_text' => 'Tetapi anda jangan melihat kepada perkara negatif yang mungkin berlaku.', 'order' => 211],
