            ['start_time' => 810.02, 'end_time' => 812.66, 'target_text' => 'As a group of people, I found Shish as well.', 'source_text' => 'Sebagai satu kumpulan manusia, saya juga mendapati perkara ini, Sheikh.', 'order' => 215],
            ['start_time' => 812.66, 'end_time' => 813.86, 'target_text' => 'I\'m sure we\'ve all witnessed it.', 'source_text' => 'Saya yakin kita semua pernah menyaksikannya.', 'order' => 216],
            ['start_time' => 813.86, 'end_time' => 814.66, 'target_text' => 'We\'ve been to Hajj.', 'source_text' => 'Kita pernah menunaikan haji.', 'order' => 217],
            ['start_time' => 815.3, 'end_time' => 819.54, 'target_text' => 'We find that the people that are actually in attendance', 'source_text' => 'Kita dapati orang-orang yang benar-benar hadir di sana', 'order' => 218],
            ['start_time' => 819.54, 'end_time' => 821.46, 'target_text' => 'are not always the rich people.', 'source_text' => 'tidak selalunya daripada kalangan orang kaya.', 'order' => 219],
            ['start_time' => 821.46, 'end_time' => 822.82, 'target_text' => 'The millionaires in the village.', 'source_text' => 'Jutawan-jutawan di kampung.', 'order' => 220],
            ['start_time' => 822.82, 'end_time' => 823.78, 'target_text' => 'We don\'t really see that.', 'source_text' => 'Kita tidak selalu melihat golongan itu.', 'order' => 221],
            ['start_time' => 824.34, 'end_time' => 826.18, 'target_text' => 'We find that Allah brings everybody.', 'source_text' => 'Kita dapati Allah membawa semua lapisan manusia.', 'order' => 222],
