            ['start_time' => 829.46, 'end_time' => 831.94, 'target_text' => 'are actually the people who are less fortunate than us.', 'source_text' => 'sebenarnya adalah orang-orang yang kurang bernasib baik berbanding kita.', 'order' => 225],
