            ['start_time' => 1080.34, 'end_time' => 1083.54, 'target_text' => 'Allah\'s origin, people would rush to do a Hajj.', 'source_text' => 'dengan Allah \'Azza wa Jalla, pasti orang ramai akan bergegas menunaikan haji.', 'order' => 308],
            ['start_time' => 1083.54, 'end_time' => 1085.02, 'target_text' => 'So, Palalah, nah.', 'source_text' => 'Subhanallah, benar sekali.', 'order' => 309],
