            ['start_time' => 1131.46, 'end_time' => 1134.78, 'target_text' => 'But it\'s all interconnected in a divine way.', 'source_text' => 'Tetapi semuanya saling berkait mengikut ketentuan ilahi yang maha bijaksana.', 'order' => 333],
