            ['start_time' => 1145.5, 'end_time' => 1148.62, 'target_text' => 'You know, either I\'m out of to come be shayin.', 'source_text' => 'Anda tahu sabda Nabi: \'Iza amartukum bi syai\'in\' (apabila aku perintahkan kamu sesuatu perkara),', 'order' => 340],
