            ['start_time' => 1150.3, 'end_time' => 1151.5, 'target_text' => 'The Prophet Salah, Salah, Salah says,', 'source_text' => 'Nabi Sallallahu \'Alaihi Wasallam bersabda,', 'order' => 342],
            ['start_time' => 1151.5, 'end_time' => 1153.54, 'target_text' => 'when I have instructed you to do something,', 'source_text' => '\'Apabila aku memerintahkan kamu melakukan sesuatu,', 'order' => 343],
            ['start_time' => 1153.54, 'end_time' => 1155.9, 'target_text' => 'do it to the best of your ability.', 'source_text' => 'lakukanlah ia setakat kemampuan kamu.\'', 'order' => 344],
            ['start_time' => 1155.94, 'end_time' => 1157.34, 'target_text' => 'So, don\'t wait to say,', 'source_text' => 'Oleh itu, janganlah menunggu lalu bertanya,', 'order' => 345],
            ['start_time' => 1157.34, 'end_time' => 1159.46, 'target_text' => 'was I invited, was I not invited?', 'source_text' => '\'Adakah aku dijemput atau adakah aku tidak dijemput?\'', 'order' => 346],
            ['start_time' => 1159.46, 'end_time' => 1161.5, 'target_text' => 'Whether it is your Salah, your Zakah,', 'source_text' => 'Sama ada solat anda, zakat anda,', 'order' => 347],
