            ['start_time' => 1166.62, 'end_time' => 1169.06, 'target_text' => 'and then you will find out in Shala,', 'source_text' => 'dan kemudian anda akan dapati insya-Allah,', 'order' => 351],
            ['start_time' => 1169.06, 'end_time' => 1171.22, 'target_text' => 'that Allah has really favored you', 'source_text' => 'bahawa Allah benar-benar telah mengurniakan kurniaan-Nya kepada anda', 'order' => 352],
