            ['start_time' => 1173.42, 'end_time' => 1176.3, 'target_text' => 'One thing that really impresses me a lot is,', 'source_text' => 'Satu perkara yang benar-benar amat mengagumkan saya adalah,', 'order' => 354],
            ['start_time' => 1176.3, 'end_time' => 1180.1, 'target_text' => 'when I see people whom you and I might think,', 'source_text' => 'apabila saya melihat orang-orang yang mungkin anda dan saya sangka,', 'order' => 355],
            ['start_time' => 1180.1, 'end_time' => 1182.22, 'target_text' => 'they don\'t look so practicing,', 'source_text' => 'mereka tidak kelihatan begitu warak di luaran,', 'order' => 356],
            ['start_time' => 1182.22, 'end_time' => 1186.54, 'target_text' => 'but they\'re focused on parts and aspects of the religion', 'source_text' => 'tetapi mereka sangat fokus pada aspek dan tuntutan agama tertentu', 'order' => 357],
            ['start_time' => 1186.54, 'end_time' => 1189.62, 'target_text' => 'in a bigger way than a lot of other people.', 'source_text' => 'dengan cara yang jauh lebih hebat berbanding ramai orang lain.', 'order' => 358],
            ['start_time' => 1189.62, 'end_time' => 1193.14, 'target_text' => 'So, I\'ve learned over the years that we all have weaknesses', 'source_text' => 'Maka, saya belajar sepanjang bertahun-tahun bahawa kita semua mempunyai kelemahan', 'order' => 359],
            ['start_time' => 1193.14, 'end_time' => 1194.86, 'target_text' => 'and we all have strengths.', 'source_text' => 'dan kita semua mempunyai kekuatan.', 'order' => 360],
            ['start_time' => 1194.86, 'end_time' => 1198.06, 'target_text' => 'Some of our weaknesses are so apparent,', 'source_text' => 'Sebahagian daripada kelemahan kita sangat ketara,', 'order' => 361],
            ['start_time' => 1198.06, 'end_time' => 1200.3, 'target_text' => 'and some of them are not so apparent.', 'source_text' => 'dan sebahagian lagi tersembunyi tidak kelihatan.', 'order' => 362],
            ['start_time' => 1200.3, 'end_time' => 1203.18, 'target_text' => 'And so, therefore, you never know who\'s life', 'source_text' => 'Justeru, anda tidak akan pernah tahu kehidupan siapa', 'order' => 363],
            ['start_time' => 1203.18, 'end_time' => 1207.94, 'target_text' => 'Allah wants to change completely through something', 'source_text' => 'yang Allah ingin ubah sepenuhnya melalui satu ibadah agung', 'order' => 364],
