            ['start_time' => 1209.22, 'end_time' => 1211.14, 'target_text' => 'I\'ve seen people go for Hajj come back,', 'source_text' => 'Saya pernah melihat orang pergi menunaikan haji dan kembali,', 'order' => 366],
            ['start_time' => 1211.14, 'end_time' => 1213.1, 'target_text' => 'totally transformed, like you won\'t imagine,', 'source_text' => 'berubah secara menyeluruh, sehingga anda tidak dapat bayangkan', 'order' => 367],
            ['start_time' => 1213.1, 'end_time' => 1214.5, 'target_text' => 'this was the same person who went.', 'source_text' => 'bahawa ini adalah individu yang sama yang pernah pergi dahulu.', 'order' => 368],
            ['start_time' => 1214.5, 'end_time' => 1217.14, 'target_text' => 'So, I\'ve seen others, they come back', 'source_text' => 'Namun saya juga pernah melihat orang lain, mereka pulang', 'order' => 369],
            ['start_time' => 1217.14, 'end_time' => 1219.38, 'target_text' => 'and talk about it like they went into the holiday.', 'source_text' => 'dan menceritakannya seolah-olah mereka sekadar pergi bercuti santai.', 'order' => 370],
            ['start_time' => 1220.38, 'end_time' => 1221.94, 'target_text' => 'So, I\'ve found a lot.', 'source_text' => 'Subhanallah, saya telah melihat banyak keadaan begitu.', 'order' => 371],
            ['start_time' => 1221.94, 'end_time' => 1224.5, 'target_text' => 'And the difference between both of them would be', 'source_text' => 'Dan perbezaan ketara antara kedua-duanya ialah', 'order' => 372],
            ['start_time' => 1224.5, 'end_time' => 1227.7, 'target_text' => 'that one went with knowledge,', 'source_text' => 'yang seorang itu pergi berbekalkan ilmu,', 'order' => 373],
            ['start_time' => 1227.7, 'end_time' => 1230.22, 'target_text' => 'and the other perhaps didn\'t have the knowledge', 'source_text' => 'manakala yang seorang lagi mungkin tidak mempunyai ilmu', 'order' => 374],
            ['start_time' => 1230.22, 'end_time' => 1232.22, 'target_text' => 'that he requires to do at Hajj.', 'source_text' => 'yang diperlukan untuk menunaikan ibadah haji.', 'order' => 375],
            ['start_time' => 1232.22, 'end_time' => 1234.06, 'target_text' => 'That\'s going to be the difference', 'source_text' => 'Itulah yang menjadi pemutus perbezaan', 'order' => 376],
            ['start_time' => 1234.06, 'end_time' => 1236.5, 'target_text' => 'in terms of whether the Hajj is going to have an effect', 'source_text' => 'sama ada ibadah haji itu akan memberi kesan mendalam', 'order' => 377],
            ['start_time' => 1236.5, 'end_time' => 1237.62, 'target_text' => 'on you or not.', 'source_text' => 'ke atas jiwa anda atau sebaliknya.', 'order' => 378],
            ['start_time' => 1237.62, 'end_time' => 1239.46, 'target_text' => 'That\'s why Allah is Zawajen.', 'source_text' => 'Itulah sebabnya Allah \'Azza wa Jalla,', 'order' => 379],
            ['start_time' => 1239.46, 'end_time' => 1243.22, 'target_text' => 'He said, once you have made the intention to do a Hajj,', 'source_text' => 'Dia berfirman, apabila anda telah berniat menunaikan haji,', 'order' => 380],
            ['start_time' => 1243.22, 'end_time' => 1245.34, 'target_text' => 'from unfollowed by if you hidden a Hajj,', 'source_text' => '\'Faman faradha fihinnal hajja\' (sesiapa yang menetapkan niatnya untuk haji),', 'order' => 381],
            ['start_time' => 1245.34, 'end_time' => 1247.14, 'target_text' => 'Allah Zawajen, he says,', 'source_text' => 'Allah \'Azza wa Jalla berfirman,', 'order' => 382],
            ['start_time' => 1247.14, 'end_time' => 1249.58, 'target_text' => 'later on in the air, what does a wadu?', 'source_text' => 'dalam ayat seterusnya: \'Wa tazawwadu\' (berbekallah kamu).', 'order' => 383],
            ['start_time' => 1249.58, 'end_time' => 1250.42, 'target_text' => 'Prepare.', 'source_text' => 'Buatlah persiapan dan persediaan.', 'order' => 384],
            ['start_time' => 1250.42, 'end_time' => 1253.06, 'target_text' => 'Then he said, for in the Hajj, zed it, takwah.', 'source_text' => 'Kemudian Dia berfirman: \'Fa inna khayraz zaadit taqwa\'.', 'order' => 385],
            ['start_time' => 1253.06, 'end_time' => 1255.74, 'target_text' => 'The best preparation is the preparation of a takwah.', 'source_text' => 'Sebaik-baik bekal persiapan adalah bekalan takwa.', 'order' => 386],
            ['start_time' => 1255.74, 'end_time' => 1257.5, 'target_text' => 'What takwah resides in the Hajj?', 'source_text' => 'Dan takwa itu berakar umbi di dalam hati semasa haji.', 'order' => 387],
            ['start_time' => 1257.5, 'end_time' => 1260.42, 'target_text' => 'So, those who make the most out of the Hajj,', 'source_text' => 'Maka orang-orang yang memperoleh manfaat terbesar daripada haji,', 'order' => 388],
            ['start_time' => 1260.42, 'end_time' => 1263.7, 'target_text' => 'are people that prepared not only their luggage,', 'source_text' => 'adalah mereka yang bukan sekadar menyediakan beg bagasi mereka,', 'order' => 389],
            ['start_time' => 1263.7, 'end_time' => 1266.54, 'target_text' => 'but they prepared the Hajj with a takwah.', 'source_text' => 'tetapi mereka melengkapkan haji mereka dengan perisai takwa.', 'order' => 390],
            ['start_time' => 1266.54, 'end_time' => 1269.02, 'target_text' => 'And of course, preparing the Hajj with a takwah,', 'source_text' => 'Dan sudah tentu, mempersiapkan haji dengan bekal takwa', 'order' => 391],
            ['start_time' => 1269.02, 'end_time' => 1274.3, 'target_text' => 'the most definitely would include learning, seeking the knowledge', 'source_text' => 'pastinya merangkumi belajar dan menuntut ilmu yang sahih', 'order' => 392],
            ['start_time' => 1274.3, 'end_time' => 1276.98, 'target_text' => 'of how this Hajj is supposed to be performed.', 'source_text' => 'tentang bagaimana ibadah haji ini sepatutnya dilaksanakan.', 'order' => 393],
            ['start_time' => 1276.98, 'end_time' => 1279.62, 'target_text' => 'This would enhance your experience.', 'source_text' => 'Ini akan meningkatkan penghayatan dan pengalaman anda.', 'order' => 394],
            ['start_time' => 1279.62, 'end_time' => 1282.5, 'target_text' => 'And as a result, it will create a dramatic change', 'source_text' => 'Dan hasilnya, ia akan mencetuskan perubahan yang sangat mendalam', 'order' => 395],
            ['start_time' => 1282.5, 'end_time' => 1284.82, 'target_text' => 'in your attitude, in your behavior,', 'source_text' => 'pada sikap anda, pada akhlak anda,', 'order' => 396],
            ['start_time' => 1284.82, 'end_time' => 1288.62, 'target_text' => 'in how you become early, later on, after a Hajj.', 'source_text' => 'pada keperibadian anda seterusnya selepas menunaikan haji.', 'order' => 397],
            ['start_time' => 1288.62, 'end_time' => 1291.1, 'target_text' => 'Now, for in the Hajj, zed it takwah,', 'source_text' => 'Kerana sesungguhnya sebaik-baik bekal itu adalah takwa,', 'order' => 398],
            ['start_time' => 1291.1, 'end_time' => 1291.94, 'target_text' => 'sophanAllah.', 'source_text' => 'Subhanallah.', 'order' => 399],
            ['start_time' => 1291.94, 'end_time' => 1293.34, 'target_text' => 'Patan Ali, sophanAllah, hu\'ali, hu\'ali, hu\'ali, hu\'ali,', 'source_text' => 'Maha Suci Allah, sungguh indah dan mendalam.', 'order' => 400],
            ['start_time' => 1293.34, 'end_time' => 1295.14, 'target_text' => 'hu\'ali, hu\'ali.', 'source_text' => 'Sallallahu \'alaihi wasallam.', 'order' => 401],
            ['start_time' => 1295.18, 'end_time' => 1299.78, 'target_text' => 'Before he went to Allah\'azou asian in the heavens,', 'source_text' => 'Sebelum Baginda mikraj bertemu Allah \'Azza wa Jalla di langit,', 'order' => 402],
            ['start_time' => 1299.78, 'end_time' => 1302.02, 'target_text' => 'in the journey of an historical marriage,', 'source_text' => 'dalam peristiwa agung Israk dan Mikraj,', 'order' => 403],
            ['start_time' => 1303.5, 'end_time' => 1306.34, 'target_text' => 'Jabri\'ali, his salam came to his house.', 'source_text' => 'Jibril \'Alaihissalam telah datang ke rumah Baginda.', 'order' => 404],
            ['start_time' => 1306.34, 'end_time' => 1308.78, 'target_text' => 'Opened his chest, took his heart out,', 'source_text' => 'Membelah dada Baginda, mengeluarkan hati Baginda,', 'order' => 405],
            ['start_time' => 1308.78, 'end_time' => 1312.78, 'target_text' => 'washed it with zamsam, filled it with knowledge and wisdom,', 'source_text' => 'membasuhnya dengan air zamzam, mengisinya dengan ilmu dan hikmah,', 'order' => 406],
            ['start_time' => 1312.78, 'end_time' => 1314.78, 'target_text' => 'and pulled it back in and stitched.', 'source_text' => 'lalu mengembalikannya semula ke tempatnya dan mencantumkannya kembali.', 'order' => 407],
            ['start_time' => 1314.78, 'end_time' => 1317.42, 'target_text' => 'Afterwards, he did the journey, the night journey', 'source_text' => 'Selepas itu, barulah Baginda memulakan perjalanan malam', 'order' => 408],
            ['start_time' => 1317.42, 'end_time' => 1318.6, 'target_text' => 'from Makkah to Jerusalem,', 'source_text' => 'dari Makkah ke Baitulmaqdis,', 'order' => 409],
            ['start_time' => 1318.6, 'end_time' => 1322.34, 'target_text' => 'and then the ascension from Jerusalem to the heavens.', 'source_text' => 'dan seterusnya mikraj naik dari Baitulmaqdis ke langit tertinggi.', 'order' => 410],
            ['start_time' => 1322.34, 'end_time' => 1324.42, 'target_text' => 'Because he was meeting Allah asou asian,', 'source_text' => 'Kerana Baginda akan mengadap Allah \'Azza wa Jalla,', 'order' => 411],
            ['start_time' => 1324.46, 'end_time' => 1327.22, 'target_text' => 'the heart had to be purified and cleansed and filled', 'source_text' => 'maka hatinya perlu disucikan, dibersihkan dan dipenuhi', 'order' => 412],
            ['start_time' => 1327.22, 'end_time' => 1328.94, 'target_text' => 'with knowledge and wisdom.', 'source_text' => 'dengan limpahan ilmu dan hikmah.', 'order' => 413],
            ['start_time' => 1328.94, 'end_time' => 1331.26, 'target_text' => 'And the journey to the house of Allah asou asian', 'source_text' => 'Dan perjalanan menuju ke Baitullah (rumah Allah \'Azza wa Jalla)', 'order' => 414],
            ['start_time' => 1331.26, 'end_time' => 1333.78, 'target_text' => 'is like meeting Allah sophanAllah, hu\'ali, hu\'ali, hu\'ali.', 'source_text' => 'adalah seumpama perjumpaan menghadap Allah, Subhanallah.', 'order' => 415],
            ['start_time' => 1333.78, 'end_time' => 1336.18, 'target_text' => 'That\'s what it is, because when we see the cover,', 'source_text' => 'Itulah hakikatnya, kerana apabila kita melihat Kaabah,', 'order' => 416],
            ['start_time' => 1336.18, 'end_time' => 1337.82, 'target_text' => 'we say Allah and the salam,', 'source_text' => 'kita berdoa: \'Allahumma Antas Salam\',', 'order' => 417],
            ['start_time' => 1337.82, 'end_time' => 1339.06, 'target_text' => 'wa minkah salam,', 'source_text' => '\'wa minkas salam\',', 'order' => 418],
            ['start_time' => 1339.06, 'end_time' => 1340.66, 'target_text' => 'for how you now obey this salam,', 'source_text' => '\'fahayyina Rabbana bis salam\' (Ya Allah, Engkaulah Kesejahteraan dan dari-Mu jua kesejahteraan),', 'order' => 419],
            ['start_time' => 1340.66, 'end_time' => 1342.98, 'target_text' => 'which are the very same words the believers say', 'source_text' => 'iaitu ucapan yang sama diungkapkan oleh orang-orang beriman', 'order' => 420],
            ['start_time' => 1342.98, 'end_time' => 1345.66, 'target_text' => 'when they enter the paradise and say they Lord.', 'source_text' => 'apabila mereka melangkah masuk ke syurga dan melihat Tuhan mereka.', 'order' => 421],
            ['start_time' => 1345.66, 'end_time' => 1348.66, 'target_text' => 'So, because it\'s a journey to Allah asou asian,', 'source_text' => 'Oleh itu, kerana ia adalah satu perjalanan menuju Allah \'Azza wa Jalla,', 'order' => 422],
            ['start_time' => 1348.66, 'end_time' => 1350.3, 'target_text' => 'the heart needs to be prepared as all.', 'source_text' => 'hati juga perlu dipersiapkan sepenuhnya.', 'order' => 423],
            ['start_time' => 1350.3, 'end_time' => 1353.18, 'target_text' => 'We need to fill it up with that knowledge and that wisdom,', 'source_text' => 'Kita perlu memenuhinya dengan ilmu pengetahuan dan hikmah tersebut,', 'order' => 424],
            ['start_time' => 1353.18, 'end_time' => 1355.42, 'target_text' => 'and this is why it is important.', 'source_text' => 'dan inilah sebabnya mengapa ia sangat penting.', 'order' => 425],
            ['start_time' => 1355.42, 'end_time' => 1358.58, 'target_text' => 'So, the difference between a person changing after Allah', 'source_text' => 'Jadi, perbezaan antara orang yang berubah selepas haji', 'order' => 426],
            ['start_time' => 1358.58, 'end_time' => 1362.54, 'target_text' => 'and someone that experienced it as a holiday,', 'source_text' => 'dengan seseorang yang melaluinya sekadar seperti sebuah percutian,', 'order' => 427],
            ['start_time' => 1362.54, 'end_time' => 1364.54, 'target_text' => 'Allah or Allah would be the preparation,', 'source_text' => 'demi Allah, terletak pada persiapannya,', 'order' => 428],
            ['start_time' => 1364.54, 'end_time' => 1366.9, 'target_text' => 'the spiritual preparation last night.', 'source_text' => 'iaitu persiapan rohani dan persediaan jiwa.', 'order' => 429],
            ['start_time' => 1366.9, 'end_time' => 1370.3, 'target_text' => 'The ayah from Surat al-Rah and also mentions this as well,', 'source_text' => 'Ayat daripada Surah Ali \'Imran juga ada menyebut tentang perkara ini,', 'order' => 430],
            ['start_time' => 1370.3, 'end_time' => 1372.62, 'target_text' => 'before what it lay out, and as you had your baby,', 'source_text' => 'sebelum firman-Nya: \'Wa lillahi \'alan nasi hijjul baiti\'', 'order' => 431],
            ['start_time' => 1372.62, 'end_time' => 1375.18, 'target_text' => 'had your baby, when it\'s supply, it ain\'t sabbirah.', 'source_text' => '\'manistatha\'a ilaihi sabila\' (kewajipan manusia terhadap Allah untuk menunaikan haji bagi yang mampu).', 'order' => 432],
            ['start_time' => 1375.18, 'end_time' => 1377.02, 'target_text' => 'In that, oh, what a baby, it ain\'t sabbirah.', 'source_text' => 'Bagi sesiapa yang berkemampuan mengadakan perjalanan ke sana.', 'order' => 433],
            ['start_time' => 1377.02, 'end_time' => 1378.34, 'target_text' => 'Just like that, it ain\'t sabbirah.', 'source_text' => 'Tepat seperti itu, kemampuan untuk menempuh perjalanan.', 'order' => 434],
            ['start_time' => 1378.34, 'end_time' => 1380.74, 'target_text' => 'But who didn\'t mean to add, I mean,', 'source_text' => 'Dan sebagai petunjuk bagi sekalian manusia.', 'order' => 435],
            ['start_time' => 1380.74, 'end_time' => 1382.94, 'target_text' => 'the first day of hadges, the eighth day', 'source_text' => 'Hari pertama amalan haji iaitu hari kelapan Zulhijjah (Hari Tarwiyah),', 'order' => 436],
            ['start_time' => 1382.94, 'end_time' => 1385.14, 'target_text' => 'that we\'ll probably discuss in other episodes', 'source_text' => 'yang mungkin akan kita bincangkan dalam episod-episod seterusnya', 'order' => 437],
            ['start_time' => 1385.14, 'end_time' => 1386.3, 'target_text' => 'to come to shut Allah.', 'source_text' => 'yang akan datang, insya-Allah.', 'order' => 438],
            ['start_time' => 1386.3, 'end_time' => 1387.66, 'target_text' => 'But this day, for those who know,', 'source_text' => 'Tetapi hari ini, bagi mereka yang memahaminya,', 'order' => 439],
            ['start_time' => 1387.66, 'end_time' => 1390.9, 'target_text' => 'they perceive it to be a day where you relax', 'source_text' => 'segelintir orang menganggapnya sebagai hari untuk berehat santai', 'order' => 440],
            ['start_time' => 1390.9, 'end_time' => 1392.94, 'target_text' => 'in minna, you know, the Torah we are very easy,', 'source_text' => 'di Mina, hari Tarwiyah yang sangat tenang,', 'order' => 441],
            ['start_time' => 1392.94, 'end_time' => 1395.26, 'target_text' => 'because the day after it\'s the day of the heart of now,', 'source_text' => 'kerana keesokan harinya adalah Hari Arafah,', 'order' => 442],
            ['start_time' => 1395.3, 'end_time' => 1397.5, 'target_text' => 'however, this day is the idea of relaxing really.', 'source_text' => 'walau bagaimanapun, hakikat hari ini bukanlah semata-mata untuk bersenang-lenang.', 'order' => 443],
            ['start_time' => 1397.5, 'end_time' => 1399.66, 'target_text' => 'It\'s a day of full preparation,', 'source_text' => 'Ia adalah hari persiapan yang penuh dan mendalam,', 'order' => 444],
            ['start_time' => 1399.66, 'end_time' => 1401.82, 'target_text' => 'being ready from the heart, like the Shess mentioned.', 'source_text' => 'bersiap siaga dari sudut hati, seperti yang Sheikh sebutkan tadi.', 'order' => 445],
            ['start_time' => 1401.82, 'end_time' => 1403.1, 'target_text' => 'And Allah sabbirah to Allah mentions', 'source_text' => 'Dan Allah Subhanahu wa Ta\'ala berfirman:', 'order' => 446],
            ['start_time' => 1403.1, 'end_time' => 1404.74, 'target_text' => 'where who didn\'t mean to add, I mean,', 'source_text' => '\'Hudan lin-naas\' (petunjuk bagi sekalian manusia),', 'order' => 447],
            ['start_time' => 1404.74, 'end_time' => 1406.62, 'target_text' => 'for all of the people who have touched power,', 'source_text' => 'bagi semua orang yang mempunyai ketakwaan,', 'order' => 448],
            ['start_time' => 1406.62, 'end_time' => 1408.1, 'target_text' => 'this is to be a guidance for them.', 'source_text' => 'ia menjadi petunjuk dan panduan buat mereka.', 'order' => 449],
            ['start_time' => 1408.1, 'end_time' => 1410.14, 'target_text' => 'It reminded me of one of the people of the past,', 'source_text' => 'Ini mengingatkan saya kepada salah seorang ulama terdahulu,', 'order' => 450],
            ['start_time' => 1410.14, 'end_time' => 1411.7, 'target_text' => 'Shafiya and Ibn Oriayina,', 'source_text' => 'Sufyan bin \'Uyaynah rahimahullah,', 'order' => 451],
            ['start_time' => 1411.7, 'end_time' => 1414.06, 'target_text' => 'he says, shahit to them, and in a more different.', 'source_text' => 'beliau pernah berkata: \'Syahidtu Arafata thamanina marrah\'.', 'order' => 452],
            ['start_time' => 1414.06, 'end_time' => 1417.3, 'target_text' => 'I witnessed out of her 80 times,', 'source_text' => '\'Aku telah menyaksikan dan berwukuf di Arafah sebanyak 80 kali.\'', 'order' => 453],
            ['start_time' => 1417.3, 'end_time' => 1419.66, 'target_text' => 'and his secret was that every year at out of her,', 'source_text' => 'Dan rahsianya adalah setiap tahun di Arafah,', 'order' => 454],
            ['start_time' => 1419.66, 'end_time' => 1421.1, 'target_text' => 'because of the guidance he took,', 'source_text' => 'kerana petunjuk hidayah yang diperolehnya,', 'order' => 455],
            ['start_time' => 1421.1, 'end_time' => 1422.94, 'target_text' => 'and because of the blessings he took,', 'source_text' => 'dan kerana limpahan keberkatan yang diraihnya,', 'order' => 456],
            ['start_time' => 1422.94, 'end_time' => 1424.9, 'target_text' => 'and because of how much his heart was engaged', 'source_text' => 'serta betapa khusyuk dan terpautnya hatinya,', 'order' => 457],
            ['start_time' => 1424.9, 'end_time' => 1427.22, 'target_text' => 'that Allah, the Almighty, used to make do add,', 'source_text' => 'kepada Allah Yang Maha Kuasa, beliau sentiasa berdoa,', 'order' => 458],
            ['start_time' => 1427.22, 'end_time' => 1429.82, 'target_text' => 'and he used to ask Allah to not make this the final year.', 'source_text' => 'dan beliau memohon kepada Allah agar tidak menjadikan tahun itu sebagai tahun terakhirnya.', 'order' => 459],
            ['start_time' => 1429.82, 'end_time' => 1432.26, 'target_text' => 'So he would come back year after year, year after year,', 'source_text' => 'Maka beliau terus kembali tahun demi tahun, tahun demi tahun,', 'order' => 460],
            ['start_time' => 1432.26, 'end_time' => 1434.54, 'target_text' => 'year after year, and so the final year,', 'source_text' => 'tahun demi tahun, hinggalah pada tahun terakhir hidupnya,', 'order' => 461],
            ['start_time' => 1434.54, 'end_time' => 1437.46, 'target_text' => 'he didn\'t make that doh had, and he didn\'t come back.', 'source_text' => 'beliau tidak lagi memanjatkan doa itu, dan selepas itu beliau wafat dan tidak kembali lagi.', 'order' => 462],
            ['start_time' => 1437.46, 'end_time' => 1439.18, 'target_text' => 'So it shows some handle of what you take away', 'source_text' => 'Maka ini membuktikan Subhanallah, apa yang anda peroleh', 'order' => 463],
            ['start_time' => 1439.18, 'end_time' => 1440.7, 'target_text' => 'from how it is really great.', 'source_text' => 'daripada ibadah haji adalah sesuatu yang teramat agung.', 'order' => 464],
            ['start_time' => 1440.7, 'end_time' => 1442.98, 'target_text' => 'And Allah sabbirah to Allah blesses you to come', 'source_text' => 'Dan Allah Subhanahu wa Ta\'ala memberkati kedatangan anda', 'order' => 465],
            ['start_time' => 1442.98, 'end_time' => 1444.94, 'target_text' => 'with the effort that you make beforehand,', 'source_text' => 'setimpal dengan usaha gigih yang anda lakukan sebelumnya,', 'order' => 466],
            ['start_time' => 1444.94, 'end_time' => 1447.14, 'target_text' => 'you will really and truly find yourself', 'source_text' => 'anda benar-benar akan mendapati diri anda,', 'order' => 467],
            ['start_time' => 1447.14, 'end_time' => 1449.34, 'target_text' => 'like Shavmufthi mentioned before.', 'source_text' => 'sebagaimana yang telah disebutkan oleh Sheikh Mufti sebentar tadi.', 'order' => 468],
            ['start_time' => 1449.34, 'end_time' => 1451.26, 'target_text' => 'In a way that you\'ve never been with Allah sabbirah,', 'source_text' => 'Berada dalam satu kedekatan yang belum pernah anda rasakan dengan Allah Subhanahu wa Ta\'ala,', 'order' => 469],
            ['start_time' => 1451.26, 'end_time' => 1452.58, 'target_text' => 'Allah before.', 'source_text' => 'sebelum ini.', 'order' => 470],
            ['start_time' => 1452.58, 'end_time' => 1457.9, 'target_text' => 'And inspires me a lot is when I, in Hajj and in Amra,', 'source_text' => 'Dan apa yang amat memberi inspirasi kepada saya semasa di haji dan umrah,', 'order' => 471],
            ['start_time' => 1457.9, 'end_time' => 1461.18, 'target_text' => 'when I see people from all over the world,', 'source_text' => 'apabila saya melihat manusia datang dari segenap pelosok dunia,', 'order' => 472],
            ['start_time' => 1461.18, 'end_time' => 1462.78, 'target_text' => 'all over the world, different colors,', 'source_text' => 'dari seluruh dunia, pelbagai warna kulit,', 'order' => 473],
            ['start_time' => 1462.78, 'end_time' => 1465.66, 'target_text' => 'different sizes, different backgrounds,', 'source_text' => 'pelbagai bentuk rupa, pelbagai latar belakang hidup,', 'order' => 474],
            ['start_time' => 1465.66, 'end_time' => 1468.86, 'target_text' => 'completely, and I tell myself, Allah,', 'source_text' => 'yang berbeza sama sekali, dan saya berkata pada diri saya: Ya Allah,', 'order' => 475],
            ['start_time' => 1468.86, 'end_time' => 1470.82, 'target_text' => 'Allah loves this person so much', 'source_text' => 'Allah amat menyayangi insan ini', 'order' => 476],
            ['start_time' => 1470.82, 'end_time' => 1473.42, 'target_text' => 'that he brought them to his house.', 'source_text' => 'sehingga Dia menjemput dan membawa mereka ke rumah-Nya.', 'order' => 477],
            ['start_time' => 1473.42, 'end_time' => 1474.82, 'target_text' => 'You see people can barely walk,', 'source_text' => 'Anda melihat ada orang yang hampir tidak berdaya untuk berjalan,', 'order' => 478],
            ['start_time' => 1474.82, 'end_time' => 1476.66, 'target_text' => 'you see people from all over the world,', 'source_text' => 'anda melihat orang ramai dari seluruh pelosok dunia,', 'order' => 479],
            ['start_time' => 1476.66, 'end_time' => 1477.94, 'target_text' => 'from the third world countries,', 'source_text' => 'dari negara-negara dunia ketiga,', 'order' => 480],
            ['start_time' => 1477.94, 'end_time' => 1481.26, 'target_text' => 'like you say, literally poor people, otherwise,', 'source_text' => 'seperti yang anda katakan, orang yang serba daif dari sudut kebendaan,', 'order' => 481],
            ['start_time' => 1481.26, 'end_time' => 1484.38, 'target_text' => 'they made it, they saved up, they came for the sake', 'source_text' => 'namun mereka berjaya sampai, mereka menabung, mereka datang semata-mata demi', 'order' => 482],
            ['start_time' => 1484.38, 'end_time' => 1485.9, 'target_text' => 'of Allah, Allah brought them.', 'source_text' => 'kerana Allah, dan Allah yang membawa mereka ke sini.', 'order' => 483],
            ['start_time' => 1485.9, 'end_time' => 1489.7, 'target_text' => 'He loves them so much that he brought them there in the crowd.', 'source_text' => 'Dia amat menyayangi mereka sehingga Dia menghimpunkan mereka di tengah-tengah lautan manusia.', 'order' => 484],
            ['start_time' => 1489.7, 'end_time' => 1491.94, 'target_text' => 'They are slowly walking around the Kaaba,', 'source_text' => 'Mereka melangkah perlahan-lahan mengelilingi Kaabah,', 'order' => 485],
            ['start_time' => 1491.94, 'end_time' => 1494.58, 'target_text' => 'they don\'t care whether it takes two hours or 10 hours.', 'source_text' => 'mereka tidak peduli sama ada ia mengambil masa dua jam atau sepuluh jam.', 'order' => 486],
            ['start_time' => 1494.58, 'end_time' => 1496.66, 'target_text' => 'They don\'t care, they don\'t complain.', 'source_text' => 'Mereka tidak kisah, mereka tidak pernah mengeluh.', 'order' => 487],
            ['start_time' => 1496.66, 'end_time' => 1499.26, 'target_text' => 'The fact that they\'re there, it inspires me so much', 'source_text' => 'Hakikat bahawa mereka berada di situ, ia memberi inspirasi yang begitu mendalam kepada saya', 'order' => 488],
            ['start_time' => 1499.26, 'end_time' => 1502.82, 'target_text' => 'because I tell myself, I am just one like they are.', 'source_text' => 'kerana saya berkata kepada diri saya: Aku hanyalah salah seorang hamba sama seperti mereka.', 'order' => 489],
            ['start_time' => 1502.82, 'end_time' => 1505.54, 'target_text' => 'Now I am no better than any of them.', 'source_text' => 'Aku tidak lebih baik daripada sesiapa pun di antara mereka.', 'order' => 490],
            ['start_time' => 1505.54, 'end_time' => 1508.98, 'target_text' => 'There is no superiority if anything I\'m worse.', 'source_text' => 'Tiada kelebihan darjat, malah mungkin aku yang lebih serba kekurangan.', 'order' => 491],
            ['start_time' => 1508.98, 'end_time' => 1511.42, 'target_text' => 'And that\'s why we\'re wearing the same clothing.', 'source_text' => 'Dan itulah sebabnya kita semua memakai pakaian ihram yang sama.', 'order' => 492],
            ['start_time' => 1511.42, 'end_time' => 1514.54, 'target_text' => 'We shouldn\'t be conspicuous with any fragrance,', 'source_text' => 'Kita tidak wajar menonjol dengan sebarang wangian,', 'order' => 493],
            ['start_time' => 1514.54, 'end_time' => 1517.22, 'target_text' => 'we shouldn\'t be conspicuous with any other things,', 'source_text' => 'kita tidak wajar bermegah dengan apa-apa perhiasan lain,', 'order' => 494],
            ['start_time' => 1517.22, 'end_time' => 1518.98, 'target_text' => 'and we are just the same.', 'source_text' => 'dan kita semua berdiri sama rata di sisi Allah.', 'order' => 495],
            ['start_time' => 1518.98, 'end_time' => 1521.94, 'target_text' => 'It\'s Allah Almighty, that invitation,', 'source_text' => 'Semuanya adalah kerana Allah Yang Maha Kuasa, itulah jemputan-Nya,', 'order' => 496],
            ['start_time' => 1521.94, 'end_time' => 1524.3, 'target_text' => 'Allah invited them and they came.', 'source_text' => 'Allah menjemput mereka dan mereka menyahut panggilan itu.', 'order' => 497],
            ['start_time' => 1525.34, 'end_time' => 1526.66, 'target_text' => 'And I always tell myself,', 'source_text' => 'Dan saya sentiasa berdoa kepada diri saya sendiri,', 'order' => 498],
            ['start_time' => 1526.66, 'end_time' => 1529.78, 'target_text' => 'Allah, keep inviting, and let me keep coming.', 'source_text' => '\'Ya Allah, teruskanlah menjemputku, dan izinkanlah daku sentiasa berkunjung ke rumah-Mu.\'', 'order' => 499],
            ['start_time' => 1529.78, 'end_time' => 1533.06, 'target_text' => 'Allah, make it easy, grant us good days.', 'source_text' => 'Ya Allah, permudahkanlah urusan kami dan kurniakanlah kami hari-hari yang diberkati.', 'order' => 500],
            ['start_time' => 1533.06, 'end_time' => 1536.02, 'target_text' => 'Maybe we conclude with one story I remember about', 'source_text' => 'Mungkin kita boleh akhiri dengan sebuah kisah yang saya ingati tentang', 'order' => 501],
            ['start_time' => 1536.02, 'end_time' => 1539.66, 'target_text' => 'one of the Salaf Al-Iyib-Nawafak,', 'source_text' => 'salah seorang ulama Salaf, \'Ali bin al-Muwaffaq,', 'order' => 502],
            ['start_time' => 1539.66, 'end_time' => 1540.86, 'target_text' => 'or him of Allah.', 'source_text' => 'rahimahullah.', 'order' => 503],
            ['start_time' => 1540.86, 'end_time' => 1544.14, 'target_text' => 'He had done Hajj 60 times.', 'source_text' => 'Beliau telah menunaikan ibadah haji sebanyak 60 kali.', 'order' => 504],
            ['start_time' => 1545.02, 'end_time' => 1547.7, 'target_text' => 'And every single year he was a Al-Haj,', 'source_text' => 'Dan setiap kali beliau menunaikan haji,', 'order' => 505],
            ['start_time' => 1547.7, 'end_time' => 1551.42, 'target_text' => 'he\'d ask Allah Azozul to bring him back to Al-Haj.', 'source_text' => 'beliau sentiasa memohon kepada Allah \'Azza wa Jalla agar mengembalikannya semula menunaikan haji.', 'order' => 506],
            ['start_time' => 1551.42, 'end_time' => 1555.3, 'target_text' => 'And after 60 Hajj, he is to have an Allah.', 'source_text' => 'Dan selepas 60 kali menunaikan haji, Subhanallah,', 'order' => 507],
            ['start_time' => 1555.3, 'end_time' => 1556.86, 'target_text' => 'He became embarrassed.', 'source_text' => 'beliau merasa segan dan malu.', 'order' => 508],
            ['start_time' => 1556.86, 'end_time' => 1558.22, 'target_text' => 'Yeah, and he was shy.', 'source_text' => 'Ya, beliau merasa sangat malu dalam dirinya.', 'order' => 509],
            ['start_time' => 1558.22, 'end_time' => 1561.1, 'target_text' => 'How am I gonna ask Allah Azozul to bring me back again', 'source_text' => '\'Bagaimana mungkin aku memohon kepada Allah \'Azza wa Jalla untuk mengembalikanku lagi', 'order' => 510],
            ['start_time' => 1561.1, 'end_time' => 1564.02, 'target_text' => 'to Al-Haj when I\'ve been here for 60 times?', 'source_text' => 'menunaikan haji sedangkan aku sudah ke sini sebanyak 60 kali?\'', 'order' => 511],
            ['start_time' => 1564.02, 'end_time' => 1566.02, 'target_text' => 'So he slept that night in...', 'source_text' => 'Lalu beliau tidur pada malam itu di...', 'order' => 512],
            ['start_time' => 1566.02, 'end_time' => 1567.86, 'target_text' => 'It was most delipha or minha.', 'source_text' => 'Muzdalifah atau Mina.', 'order' => 513],
            ['start_time' => 1567.86, 'end_time' => 1570.46, 'target_text' => 'He slept that night, and he saw in a dream', 'source_text' => 'Beliau tidur pada malam itu, dan beliau bermimpi', 'order' => 514],
            ['start_time' => 1570.46, 'end_time' => 1573.02, 'target_text' => 'that someone came to him and said to him,', 'source_text' => 'bahawa seseorang telah mendatanginya lalu berkata kepadanya,', 'order' => 515],
            ['start_time' => 1573.02, 'end_time' => 1581.78, 'target_text' => 'well, Al-Haj, Allah, Allah, Allah.', 'source_text' => '\'Wahai Ali bin al-Muwaffaq,\'', 'order' => 516],
            ['start_time' => 1581.78, 'end_time' => 1584.06, 'target_text' => 'He heard a voice saying to him,', 'source_text' => 'beliau mendengar satu suara berkata kepadanya:', 'order' => 517],
            ['start_time' => 1584.06, 'end_time' => 1587.3, 'target_text' => 'that, yeah, how would you translate it?', 'source_text' => '\'Wahai Ali, adakah kamu menjemput ke rumahmu...\'', 'order' => 518],
            ['start_time' => 1587.3, 'end_time' => 1589.1, 'target_text' => 'How would you translate the first part,', 'source_text' => 'Bagaimana anda menterjemahkan bahagian pertamanya,', 'order' => 519],
            ['start_time' => 1589.1, 'end_time' => 1591.34, 'target_text' => 'which is, well, Al-Haj,', 'source_text' => 'iaitu: \'Hal tad\'u ila baitika illa man tuhibb?\'', 'order' => 520],
            ['start_time' => 1591.74, 'end_time' => 1593.82, 'target_text' => 'al-Baitika, al-Lamal to Heb.', 'source_text' => '\'Ila baitika illa man tuhibb\' (ke rumahmu melainkan orang yang engkau cintai?)', 'order' => 521],
            ['start_time' => 1593.82, 'end_time' => 1596.5, 'target_text' => 'And do you invite to your house, anyone,', 'source_text' => '\'Dan adakah kamu menjemput sesiapa sahaja ke rumahmu,', 'order' => 522],
            ['start_time' => 1596.5, 'end_time' => 1599.06, 'target_text' => 'but he whom you love, as a power of love?', 'source_text' => 'melainkan orang yang engkau kasihi dan cintai?\'', 'order' => 523],
            ['start_time' => 1599.06, 'end_time' => 1601.7, 'target_text' => 'And you only invite whom you love to your house.', 'source_text' => 'Dan kamu hanya menjemput orang yang kamu sayangi ke rumahmu!', 'order' => 524],
            ['start_time' => 1601.7, 'end_time' => 1603.06, 'target_text' => 'Then it\'s a time for Fulba.', 'source_text' => 'Kemudian disambung dengan kata-kata: \'Fatuba\'', 'order' => 525],
            ['start_time' => 1603.06, 'end_time' => 1605.94, 'target_text' => 'Liman Hamal, Al-Hul, Nola, Al-Al-Makamal, Al-Al\'D.', 'source_text' => '\'li man hamalahu Mawlahu ilal maqaamil a\'la\' (Maka beruntunglah orang yang dibawa oleh Tuhannya ke maqam tertinggi).', 'order' => 526],
            ['start_time' => 1605.94, 'end_time' => 1609.9, 'target_text' => 'Glad tidying to the one who his Lord carried him,', 'source_text' => '\'Berita gembiralah buat orang yang dipimpin dan dibawa oleh Tuhannya,', 'order' => 527],
            ['start_time' => 1609.9, 'end_time' => 1612.14, 'target_text' => 'and brought him to the loftiest of places,', 'source_text' => 'dan membawanya ke tempat yang paling mulia dan agung itu.\'', 'order' => 528],
            ['start_time' => 1612.14, 'end_time' => 1614.18, 'target_text' => 'which is they for Allah and Harab,', 'source_text' => 'Iaitu para tetamu Allah di Tanah Suci.', 'order' => 529],
            ['start_time' => 1614.18, 'end_time' => 1616.98, 'target_text' => 'Masqalah Azozul, to grant us the ability to visit his house', 'source_text' => 'Kita memohon kepada Allah \'Azza wa Jalla agar mengurniakan kita kemampuan untuk mengunjungi rumah-Nya', 'order' => 530],
            ['start_time' => 1616.98, 'end_time' => 1618.3, 'target_text' => 'time and time again.', 'source_text' => 'berkali-kali dan berulang-ulang lagi.', 'order' => 531],
            ['start_time' => 1618.3, 'end_time' => 1619.18, 'target_text' => 'Now I ask him, so, Hamal,', 'source_text' => 'Dan kita memohon kepada-Nya, Maha Suci Allah,', 'order' => 532],
            ['start_time' => 1619.18, 'end_time' => 1624.22, 'target_text' => 'to either keep us sincere and ask him how to hold the eyelid to accept our righteous deeds', 'source_text' => 'untuk mengekalkan keikhlasan kita dan memohon kepada Allah Yang Maha Tinggi agar menerima segala amal soleh kita,', 'order' => 533],
            ['start_time' => 1624.22, 'end_time' => 1627.74, 'target_text' => 'and our actions and our intentions in the holy or vertical kadirali.', 'source_text' => 'perbuatan kita dan niat kita, sesungguhnya Dia Maha Kuasa atas segala sesuatu.', 'order' => 534],
            ['start_time' => 1627.74, 'end_time' => 1628.74, 'target_text' => 'So let\'s go.', 'source_text' => 'Jazakumullah khairan.', 'order' => 535],
            ['start_time' => 1628.74, 'end_time' => 1629.74, 'target_text' => 'Thank you very much.', 'source_text' => 'Terima kasih banyak-banyak.', 'order' => 536],
            ['start_time' => 1629.74, 'end_time' => 1630.74, 'target_text' => 'Thank you very much.', 'source_text' => 'Terima kasih banyak-banyak.', 'order' => 537],
            ['start_time' => 1630.74, 'end_time' => 1631.74, 'target_text' => 'Thank you very much.', 'source_text' => 'Terima kasih banyak-banyak.', 'order' => 538],
            ['start_time' => 1631.74, 'end_time' => 1632.74, 'target_text' => 'Thank you very much.', 'source_text' => 'Terima kasih banyak-banyak.', 'order' => 539],
            ['start_time' => 1632.74, 'end_time' => 1633.74, 'target_text' => 'Thank you.', 'source_text' => 'Terima kasih.', 'order' => 540],
            ['start_time' => 1633.74, 'end_time' => 1634.74, 'target_text' => 'Thank you very much.', 'source_text' => 'Terima kasih banyak-banyak.', 'order' => 541],
        ];

        // Bulk insert in chunks of 100 for maximum performance and atomicity
        $now = now();
        $chunks = array_chunk($subtitles, 100);
        foreach ($chunks as $chunk) {
            $insertData = [];
            foreach ($chunk as $item) {
                $insertData[] = [
                    'id'          => (string) Str::uuid(),
                    'video_id'    => $video->id,
                    'start_time'  => $item['start_time'],
                    'end_time'    => $item['end_time'],
                    'target_text' => $item['target_text'],
                    'source_text' => $item['source_text'],
                    'order'       => $item['order'],
                    'created_at'  => $now,
                    'updated_at'  => $now,
                ];
            }
            DB::table('video_subtitles')->insert($insertData);
        }
